<script setup lang="ts">
import { computed } from 'vue'
import { state } from '../store'
import { relation, resultExplanation, reportSafe, origin } from '../presentation'
import type { RecordData } from '../types'
import Notice from './Notice.vue'
const props = defineProps<{ report: RecordData; candidate?: boolean }>()
const cfg = computed(() => state.presentation!)
const safe = computed(() => !!cfg.value && reportSafe(props.report, cfg.value, !!props.candidate))
const label = (t: string) => relation(t, cfg.value, props.candidate, props.report.job_title)
const describe = (v: string) => resultExplanation(v, cfg.value, props.candidate, props.report.job_title)
const sections = [{ key: 'strengths', name: '相符与优势', tone: 'teal' }, { key: 'weaknesses', name: '现有差距', tone: 'amber' }, { key: 'insufficient', name: '待了解的方面', tone: 'neutral' }]
const dims = computed(() => [...props.report.dimensions].sort((a,b) => a.priority.localeCompare(b.priority) || a.dimension_id.localeCompare(b.dimension_id)))
</script>
<template>
  <Notice />
  <template v-if="safe"><div class="report-intro"><div><p class="eyebrow">{{ origin(report.data_origin) }} · {{ report.mode === 'demo' ? '本地演示规则' : 'DeepSeek AI 分析' }}</p><h2>{{ report.display_name }}<span>与 {{ report.job_title }}</span></h2><p>从具体经历出发，了解相符之处、现有差距与尚未描述的方面。</p></div><span class="pill">{{ candidate ? '岗位对照结果' : report.status }}</span></div><p class="snapshot-note">本次判据 {{ report.rubric_version }} · {{ report.rubric_snapshot?.status || '历史版本 / 未冻结' }} · {{ report.confidence === 'low' ? '建议人工复核' : '文本依据已整理' }}</p>
    <section v-if="candidate && report.fit_summary" class="structure-card" :class="['very_high','high'].includes(report.fit_summary.band) ? 'teal' : ['very_low','low'].includes(report.fit_summary.band) ? 'amber' : 'neutral'"><h3>岗位契合度 · {{ report.fit_summary.label }}</h3><p>{{ report.fit_summary.reason }}</p><p v-if="report.fit_summary.coverage">本次按 {{ report.fit_summary.coverage.known }} / {{ report.fit_summary.coverage.total }} 项已有依据判断；缺失项不参与判定。</p><p v-if="report.fit_summary.missing.length">未见相关描述（仅提示）：{{ report.fit_summary.missing.join('、') }}</p><RouterLink :to="{ path: '/compare', query: { resume: report.resume_id, job: report.job_id } }" class="button secondary small">比较其他岗位 →</RouterLink></section>
    <div class="structure-grid"><section v-for="s in sections" :key="s.key" :class="['structure-card', s.tone]"><h3>{{ s.name }} <span>{{ report.structure_view[s.key].length }}</span></h3><div v-for="d in report.structure_view[s.key]" :key="d.dimension_id"><strong>{{ d.name }}</strong><p>{{ label(s.key === 'insufficient' ? 'insufficient' : d.tier) }}</p></div><p v-if="!report.structure_view[s.key].length" class="muted">当前没有此类记录</p></section></div>
    <div class="section-heading"><h3>逐项查看依据</h3><small>结论与原文一同呈现</small></div><details v-for="d in dims" :key="d.dimension_id" class="evidence-detail" open><summary><span>{{ d.name }} <small>{{ d.priority }}</small></span><span :class="['pill', { teal: ['B4','B5'].includes(d.tier), amber: ['B1','B2','B3'].includes(d.tier) }]">{{ label(d.tier) }}</span></summary><div class="evidence-body"><p v-if="describe(d.rationale)">{{ describe(d.rationale) }}</p><p v-if="d.tier_range?.length" class="range-note">证据支持的关系范围：{{ d.tier_range.map(label).join(' — ') }}</p><p v-if="describe(d.cross_band_reason)" class="muted">{{ describe(d.cross_band_reason) }}</p><blockquote v-for="(q,i) in d.evidence" :key="i"><small>简历原文</small>{{ q }}</blockquote></div></details>
    <div class="section-heading"><h3>技能与岗位要求</h3><small>左右对照原文</small></div><details v-for="(s,i) in report.skill_levels" :key="i" class="evidence-detail"><summary><strong>{{ s.skill }}</strong><span class="pill">{{ label(s.tier) }}</span></summary><div class="evidence-body"><div class="paired-evidence"><div><h4>岗位要求 · {{ s.required_level }} 级行为判据</h4><blockquote><small>岗位原文</small>{{ s.requirement_quote }}</blockquote></div><div><h4>经历支持 · {{ s.evidence_level }} 级行为判据</h4><blockquote v-for="(q,n) in s.evidence" :key="n"><small>简历原文</small>{{ q }}</blockquote></div></div><template v-for="(hit,n) in s.anchor_hits" :key="n"><p v-if="describe(hit.feature)" class="muted">命中特征：{{ describe(hit.feature) }}</p></template></div></details>
    <details v-if="!candidate" class="evidence-detail"><summary><strong>面试准备</strong><span class="pill">{{ report.open_questions?.length || 0 }} 个待了解方面</span></summary><div class="evidence-body"><article v-for="(q,i) in report.open_questions" :key="i" class="question-item"><h4>{{ q.item }}</h4><p>{{ q.hint }}</p></article><p v-if="!report.open_questions?.length" class="muted">当前没有待验证项，可开展常规面试。</p><p v-for="(q,i) in report.followups" :key="i">{{ q.question }}</p></div></details>
    <template v-if="candidate"><details class="evidence-detail"><summary><strong>岗位要求的可评估性提示</strong></summary><div class="evidence-body"><article v-for="(f,i) in report.diagnosis?.findings" :key="i"><h4>{{ f.type }}</h4><p>{{ f.statement }}</p><blockquote>{{ f.jd_quote }}</blockquote></article><p v-if="!report.diagnosis?.findings?.length" class="muted">未发现可确定的问题。</p><p v-if="!report.diagnosis?.benchmark_available" class="muted">缺少同类岗位基准，尚未进行这一类比较。</p></div></details><details class="evidence-detail"><summary><strong>行为判据差距说明</strong></summary><div class="evidence-body"><article v-for="(g,i) in report.gap_explanations" :key="i"><h4>{{ g.skill }}</h4><div class="paired-evidence"><blockquote><small>岗位要求的行为 · 判据原文</small>{{ g.requirement }}</blockquote><blockquote><small>现有描述支持的行为 · 判据原文</small>{{ g.evidence_anchor }}</blockquote></div></article><p v-if="!report.gap_explanations?.length" class="muted">当前未发现证据层面的缺口。</p></div></details></template>
    <details class="evidence-detail"><summary><strong>版本与比较依据</strong></summary><div class="evidence-body"><p>依次比较相符及以上的维度、优先级顺序中的逐维关系，以及证据充分程度。区间使用较保守的一侧；完全相同则并列。</p><p class="version-line">画像版本 {{ report.profile_version }} · 判据 {{ report.rubric_version }} · 优先级 {{ report.priority_version }} · 模型 {{ report.model_version }}</p></div></details>
  </template><div v-else class="empty"><h3>结果暂不可展示</h3><p>内容未通过呈现检查，请刷新后重新查看。</p></div>
</template>
